<script setup lang="ts">import {computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import WeightBars from '../components/WeightBars.vue';import RankingTable from '../components/RankingTable.vue';import {number} from '../utils/format';const props=defineProps<{data:Workspace}>();const emit=defineEmits<{go:[string]}>();const run=computed(()=>props.data.runs.find(r=>r.status==='completed'));const top=computed(()=>run.value?.result.alternatives.find(a=>a.rank===1));</script><template><PageHeading code="01 / COMPARISON LOGBOOK" title="排序之前，先把判断摆上台面。" description="岩舟航运分析组 · 11人。只讨论模拟方案的指标权衡，不提供实际航行指令。"/><div class="overview-layout"><section class="lead-logbook"><span class="logbook-label">当前权重判断 / AHP CONSISTENCY</span><div class="cr-display"><b>{{number(run?.result.ahp.cr,4)}}</b><span>CR<small>声明阈值 {{number(run?.result.ahp.threshold,2)}}</small></span></div><p>{{run?.result.ahp.cr_warning?'高于阈值，请复核原矩阵；系统未改写判断值。':'当前判断未超过所设CR阈值；仍须核查业务假设。'}}</p><div class="lead-summary"><span>TOPSIS {{run?.result.topsis.available?'可计算':'不可排名'}}</span><span>{{run?.result.alternatives.length||0}}个备选方案</span></div><button class="logbook-button" @click="emit('go','results')">查看排序与敏感性　↗</button></section><aside class="margin-note"><span class="eyebrow">COMPARISON NOTE / 001</span><h2>{{top?.name||'先核查指标的辨识力'}}</h2><p>当前贴近度 {{number(top?.score,4)}}。理想点距离依赖成本/收益方向和权重，不是航行安全评价。</p><small>名次对单权重扰动的范围<br/>{{top?.min_rank??'—'}}—{{top?.max_rank??'—'}} / {{run?.result.perturbation?Math.round(run.result.perturbation*100):0}}%上下扰动</small></aside></div><section v-if="run" class="paper"><div class="section-heading"><h2>本次主特征向量权重</h2><span>成本与收益方向显式保留</span></div><WeightBars :criteria="run.result.criteria" :weights="run.result.ahp.weights"/></section><section v-if="run" class="paper"><h2>备选方案对照</h2><RankingTable :rows="run.result.alternatives"/></section></template>
